class LabelItems extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.correctAnswers=new Map,this.playerAnswers=new Map,this.labels=[],this.items=[]}connectedCallback(){this.render(),this.init()}render(){this.shadowRoot.innerHTML=`
      <section class="c-quiz">
        <slot name="labels"></slot>
        <slot name="heading"></slot>
        <slot name="content"></slot>
        <h4 role="status" aria-live="polite">
          <slot name="feedback"></slot>
        </h4>
      </section>
    `}init(){const e=this.shadowRoot.querySelector('slot[name="labels"]'),t=this.shadowRoot.querySelector('slot[name="content"]');e.addEventListener("slotchange",()=>{const t=e.assignedElements()[0];if(!t)return;this.setupLabels(t)}),t.addEventListener("slotchange",()=>{const e=t.assignedElements()[0];if(!e)return;this.setupContent(e)})}setupLabels(e){this.labels=e.querySelectorAll("[data-label]"),this.labels.forEach(e=>{e.setAttribute("draggable","true"),e.style.cursor="grab",e.addEventListener("dragstart",t=>{t.dataTransfer.setData("text/plain",e.dataset.label),e.style.cursor="grabbing"})})}setupContent(e){this.items=e.querySelectorAll("[data-item]"),this.items.forEach(e=>{this.correctAnswers.set(e.dataset.item,e.dataset.correct),this.playerAnswers.set(e.dataset.item,!1),e.addEventListener("dragover",e=>e.preventDefault()),e.addEventListener("drop",t=>{t.preventDefault();const n=t.dataTransfer.getData("text/plain");this.handleDrop(n,e)})})}makeLabel(e){const t=document.createElement("span");return t.textContent=e,t.classList.add("c-label"),t}handleDrop(e,t){const s=t.dataset.item,n=this.correctAnswers.get(s)===e;this.playerAnswers.set(s,!!n),t.dataset.status=!!n,t.classList.toggle("is-good",n),t.classList.toggle("is-bad",!n),t.querySelectorAll(".c-label").forEach(e=>e.remove()),t.appendChild(this.makeLabel(e)),this.updateFeedback(n)}updateFeedback(e){const t=this.shadowRoot.querySelector('slot[name="feedback"]').assignedElements()[0];if(!t)return;const n=[...this.playerAnswers.values()].filter(e=>e).length,s=this.items.length;n===s?t.textContent="🎉 You've sorted them all!":t.textContent=`${e?"✅ You got that one right! ":"❌ You got that one wrong. "} ${n} of ${s} labelled correctly`}}customElements.define("label-items",LabelItems)